			return output.FormatRaw(f.Format, resp, cycleColumns)
		},
	}

	cmd.Flags().StringVar(&newCycle, "new-cycle", "", "Target cycle ID to transfer items to (required)")

	return cmd
}

func newArchiveCmd(f *cmdutil.Factory) *cobra.Command {
	return &cobra.Command{
		Use:   "archive <cycle-id>",
		Short: "Archive a cycle",
