package issue

import (
	"fmt"

	"github.com/spf13/cobra"

	"github.com/plane-cli/plane-cli/internal/api"
	"github.com/plane-cli/plane-cli/internal/cmdutil"
	"github.com/plane-cli/plane-cli/internal/output"
)

// NewCmd creates the issue command.
func NewCmd(f *cmdutil.Factory) *cobra.Command {
	cmd := &cobra.Command{
		Use:     "issue",
		Aliases: []string{"i"},
		Short:   "Manage work items (issues)",
	}

	cmd.AddCommand(newListCmd(f))
	cmd.AddCommand(newGetCmd(f))
	cmd.AddCommand(newGetBySeqCmd(f))
	cmd.AddCommand(newSearchCmd(f))
	cmd.AddCommand(newCreateCmd(f))
	cmd.AddCommand(newUpdateCmd(f))
	cmd.AddCommand(newDeleteCmd(f))

	return cmd
}

var issueColumns = []output.Column{
	{Header: "ID", Field: "id"},
	{Header: "SEQ", Field: "sequence_id"},
	{Header: "NAME", Field: "name"},
	{Header: "STATE", Field: "state"},
	{Header: "PRIORITY", Field: "priority"},
	{Header: "ASSIGNEES", Field: "assignees"},
}

func workItemPath() string {
	return "workspaces/{workspace_slug}/projects/{project_id}/work-items/"
}

func newListCmd(f *cmdutil.Factory) *cobra.Command {
	var state, priority, assignee string
	var perPage int
	var cursor string

	cmd := &cobra.Command{
		Use:   "list",
		Short: "List issues in a project",
		RunE: func(cmd *cobra.Command, args []string) error {
			client, err := f.Client()
			if err != nil {
				return err
			}
			ws, proj, err := f.RequireWorkspaceAndProject()
			if err != nil {
				return err
			}

			p := api.NewPath(workItemPath()).Workspace(ws).Project(proj)
			p.QueryInt("per_page", perPage)
			p.Query("cursor", cursor)
			p.Query("state", state)
			p.Query("priority", priority)
			p.Query("assignees", assignee)

			path, err := p.Build()
			if err != nil {
				return err
			}

			resp, err := client.Get(path)
			if err != nil {
				return err
			}

			return output.FormatRaw(f.Format, resp, issueColumns)
		},
	}

	cmd.Flags().StringVar(&state, "state", "", "Filter by state ID")
	cmd.Flags().StringVar(&priority, "priority", "", "Filter by priority (urgent, high, medium, low, none)")
	cmd.Flags().StringVar(&assignee, "assignee", "", "Filter by assignee ID")
	cmd.Flags().IntVar(&perPage, "per-page", 100, "Items per page (max 100)")
	cmd.Flags().StringVar(&cursor, "cursor", "", "Pagination cursor")

	return cmd
}

func newGetCmd(f *cmdutil.Factory) *cobra.Command {
	return &cobra.Command{
		Use:   "get <issue-id-or-PROJ-123>",
		Short: "Get issue details by ID or identifier",
		Args:  cobra.ExactArgs(1),
		RunE: func(cmd *cobra.Command, args []string) error {
			issueID, err := f.ResolveIssueID(args[0])
			if err != nil {
				return err
			}

			client, err := f.Client()
			if err != nil {
				return err
			}
			ws, proj, err := f.RequireWorkspaceAndProject()
			if err != nil {
				return err
			}

			path, err := api.NewPath(workItemPath()+"{issue_id}/").
				Workspace(ws).Project(proj).Param("issue_id", issueID).Build()
			if err != nil {
				return err
			}

			resp, err := client.Get(path)
			if err != nil {
				return err
			}

			return output.FormatRaw(f.Format, resp, issueColumns)
		},
	}
}

func newGetBySeqCmd(f *cmdutil.Factory) *cobra.Command {
	return &cobra.Command{
		Use:   "get-by-seq <sequence-id>",
		Short: "Get issue by sequence ID (e.g., 42)",
		Args:  cobra.ExactArgs(1),
		RunE: func(cmd *cobra.Command, args []string) error {
			client, err := f.Client()
			if err != nil {
				return err
			}
			ws, proj, err := f.RequireWorkspaceAndProject()
			if err != nil {
				return err
			}

			path, err := api.NewPath(workItemPath()+"{issue_id}/").
				Workspace(ws).Project(proj).Param("issue_id", args[0]).Build()
			if err != nil {
				return err
			}

			resp, err := client.Get(path)
			if err != nil {
				return err
			}

			return output.FormatRaw(f.Format, resp, issueColumns)
		},
	}
}

func newSearchCmd(f *cmdutil.Factory) *cobra.Command {
	var query string

	cmd := &cobra.Command{
		Use:   "search",
		Short: "Search issues",
		RunE: func(cmd *cobra.Command, args []string) error {
			if query == "" {
				return fmt.Errorf("--query is required")
			}

			client, err := f.Client()
			if err != nil {
				return err
			}
			ws, proj, err := f.RequireWorkspaceAndProject()
			if err != nil {
				return err
			}

			path, err := api.NewPath("workspaces/{workspace_slug}/projects/{project_id}/search/").
				Workspace(ws).Project(proj).Query("search", query).Build()
			if err != nil {
				return err
			}

			resp, err := client.Get(path)
			if err != nil {
				return err
			}

			return output.FormatRaw(f.Format, resp, issueColumns)
		},
	}

	cmd.Flags().StringVar(&query, "query", "", "Search query (required)")

	return cmd
}

func newCreateCmd(f *cmdutil.Factory) *cobra.Command {
	var name, description, state, priority, parent string
	var assignees, labels []string
	var startDate, targetDate string

	cmd := &cobra.Command{
		Use:   "create",
		Short: "Create a new issue",
		RunE: func(cmd *cobra.Command, args []string) error {
			if name == "" {
				return fmt.Errorf("--name is required")
			}

			client, err := f.Client()
			if err != nil {
				return err
			}
			ws, proj, err := f.RequireWorkspaceAndProject()
			if err != nil {
				return err
			}

			path, err := api.NewPath(workItemPath()).
				Workspace(ws).Project(proj).Build()
			if err != nil {
				return err
			}

			body := map[string]interface{}{
				"name": name,
			}
			if description != "" {
				body["description_html"] = description
			}
			if state != "" {
				body["state"] = state
			}
			if priority != "" {
				body["priority"] = priority
			}
			if parent != "" {
				body["parent"] = parent
			}
			if len(assignees) > 0 {
				body["assignees"] = assignees
			}
			if len(labels) > 0 {
				body["labels"] = labels
			}
			if startDate != "" {
				body["start_date"] = startDate
			}
			if targetDate != "" {
				body["target_date"] = targetDate
			}

			resp, err := client.Post(path, body)
			if err != nil {
				return err
			}

			return output.FormatRaw(f.Format, resp, issueColumns)
		},
	}

	cmd.Flags().StringVar(&name, "name", "", "Issue name (required)")
	cmd.Flags().StringVar(&description, "description", "", "Issue description (HTML)")
	cmd.Flags().StringVar(&state, "state", "", "State ID")
	cmd.Flags().StringVar(&priority, "priority", "", "Priority: urgent, high, medium, low, none")
	cmd.Flags().StringVar(&parent, "parent", "", "Parent issue ID")
	cmd.Flags().StringSliceVar(&assignees, "assignee", nil, "Assignee user IDs (comma-separated or repeated)")
	cmd.Flags().StringSliceVar(&labels, "label", nil, "Label IDs (comma-separated or repeated)")
	cmd.Flags().StringVar(&startDate, "start-date", "", "Start date (YYYY-MM-DD)")
	cmd.Flags().StringVar(&targetDate, "target-date", "", "Target date (YYYY-MM-DD)")

	return cmd
}

