			}
			if description != "" {
				body["description_html"] = description
			}
			if state != "" {
				body["state"] = state
			}
			if priority != "" {
				body["priority"] = priority
			}
			if parent != "" {
				body["parent"] = parent
			}
			if len(assignees) > 0 {
				body["assignees"] = assignees
			}
			if len(labels) > 0 {
				body["labels"] = labels
			}
			if startDate != "" {
				body["start_date"] = startDate
			}
			if targetDate != "" {
				body["target_date"] = targetDate
			}

